--DS d_ds_assembly_hdr
SELECT inv_mast.item_id ,               assembly_hdr.labor ,         assembly_hdr.ship_partial_quantity ,             assembly_hdr.ship_incomplete_assemblies ,              assembly_hdr.print_compnts_on_pick_ticket ,            assembly_hdr.print_components_on_invoice 
,             assembly_hdr.default_disposition ,                 assembly_hdr.overall_assembly_length ,              assembly_hdr.backflush ,                 assembly_hdr.assembly_days ,                 assembly_hdr.disassembly_days ,            
assembly_hdr.labor_cost_multiplier ,         assembly_hdr.allow_oe_add_components ,            assembly_hdr.production_order_processing ,             assembly_hdr.auto_create_prod_order ,               inv_mast.item_desc ,                  assembly_hdr.class1 ,              assembly_hdr.class2 ,                  assembly_hdr.class3 ,                assembly_hdr.class4 ,                  assembly_hdr.class5 ,                  assembly_hdr.delete_flag ,             assembly_hdr.date_created ,           assembly_hdr.date_last_modified ,          assembly_hdr.last_maintained_by ,              inv_mast.serialized ,             inv_mast.track_lots ,                   assembly_hdr.pricing_option ,         assembly_hdr.print_incomplete_assemblies,          assembly_hdr.inv_mast_uid,         assembly_hdr.assembly_for_stock,         assembly_hdr.assembly_usage_accumulation,         assembly_hdr.calc_component_service_level,         assembly_hdr.allow_disassembly,         assembly_hdr.cost_of_disassembly,         assembly_hdr.prorate_cost_by,         assembly_hdr.print_return_to_stock_components,         assembly_hdr.price_return_to_stock_components,         assembly_hdr.hose_assembly_flag,         assembly_hdr.hose_overall_length,         assembly_hdr.hose_unit_of_measure,     assembly_hdr.type,     assembly_hdr.process_uid,         COALESCE(inv_mast.use_revisions_flag, 'N') use_revisions_flag     ,assembly_hdr.print_traveler_with_prodorder     ,assembly_hdr.bypass_oe_prod_order_processing     ,assembly_hdr.assembly_class_uid     ,assembly_hdr.pack_by     ,assembly_hdr.minutes_to_make     ,dbo.P21_fn_convert_minutes_to_hours_format(assembly_hdr.minutes_to_make) 'time_to_make' 
FROM assembly_hdr        
INNER JOIN inv_mast ON (inv_mast.inv_mast_uid = assembly_hdr.inv_mast_uid) 
WHERE (inv_mast.item_id = '2101052513') AND ( (assembly_hdr.delete_flag <> 'Y' ) ) 